import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse('{"title":"android Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"android","tag":"android","title":"android Tag","prev":null,"next":null,"posts":[{"title":"安卓逆向的经验记录","url":"/posts/2023-01-14-android-reverse/","date":"2023-01-14 13:05","tags":["android"],"html":"<p>2023 年，博客也开通 10 年了。我都不敢看 10 年前自己写的东西。感觉全是黑历史，不过也记录了自己一点点的成长和心境的变化。今年也将继续写，记录自己技术上的各种折腾。</p>\\n<h2 id=\\"安卓逆向初体验\\" tabindex=\\"-1\\">安卓逆向初体验 <a class=\\"header-anchor\\" href=\\"#安卓逆向初体验\\" aria-label=\\"Permalink to &quot;安卓逆向初体验&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先自己知道了一个安卓电视盒子可以看全球的电视频道，我就想着干嘛要买人家的硬件，随便找个安卓手机不也可以使用么？于是找到了电视盒子上的软件，发现人家是有校验的。不是自家硬件初始化都无法通过。\\n于是我就好奇这个硬件校验是怎么做的，带着这个好奇心，开始了安卓逆向的征程。</p>\\n<h2 id=\\"java-代码脱壳\\" tabindex=\\"-1\\">Java 代码脱壳 <a class=\\"header-anchor\\" href=\\"#java-代码脱壳\\" aria-label=\\"Permalink to &quot;Java 代码脱壳&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现在的安卓软件都会使用梆梆加固之类的软件防止别人进行逆向操作，所以第一步就是处理这个。先看到 JAVA 代码才能深入研究相关逻辑。经过同学指点，使用了一个 BlackDex 的工具。可以直接在安卓手机上进行脱壳操作。使用这个工具可以拿到 dex 文件。然后使用 jadx 输出 JAVA 代码。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">jadx</span><span style=\\"color:#005CC5\\"> -d</span><span style=\\"color:#032F62\\"> dist_fold</span><span style=\\"color:#032F62\\"> ./cookie_xxx.dex</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h3 id=\\"安卓手机抓包\\" tabindex=\\"-1\\">安卓手机抓包 <a class=\\"header-anchor\\" href=\\"#安卓手机抓包\\" aria-label=\\"Permalink to &quot;安卓手机抓包&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>拿到 JAVA 代码全部都读一遍也不现实，基于前端的逆向经验。我想先抓包看看请求内容。抓包软件使用的是 Charles 一款跨平台的抓包软件，不过是商业软件需要付费。\\n通过抓包分析到，请求全部是基于 HTTP 的，所以不需要再向安卓手机上安装抓包用的 CA 证书确实省事了不少。但是请求的数据和返回都是加密的。基于请求的字段并结合 JAVA 代码分析出加密使用的是 <code>aes-128-cbc</code> 算法。这个算法需要 key 和 iv 两个参数，那这两个参数是基于什么信息来生成的呢？通过请求带的特殊的 HTTP headers 进行猜测，应该是 <code>utctime</code> <code>mac</code> <code>model</code> 这三个参数。\\n为什么这么分析呢，因为服务器端需要进行解密，那必须要把需要的参数都告诉服务端才能把密文解密回明文。</p>\\n<h2 id=\\"加密算法逻辑分析\\" tabindex=\\"-1\\">加密算法逻辑分析 <a class=\\"header-anchor\\" href=\\"#加密算法逻辑分析\\" aria-label=\\"Permalink to &quot;加密算法逻辑分析&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>来到这里，最重要的是需要知道如何生成 key 和 iv 参数，因为 aes 是对称加密，我们知道这两个参数就能把密文再解析回明文。那就带着这个疑问来去读 JAVA 代码。</p>\\n<div class=\\"language-java line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">java</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">public</span><span style=\\"color:#D73A49\\"> class</span><span style=\\"color:#6F42C1\\"> EncryptRule</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    private</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getEncrypKey</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String substring </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> MACUtils.</span><span style=\\"color:#6F42C1\\">getMac</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> MD5Util.</span><span style=\\"color:#6F42C1\\">getStringMD5_32</span><span style=\\"color:#24292E\\">(substring </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> \\"k3k7a3mM\\"</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> str).</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">8</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">24</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    private</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getDecrypKey</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String substring </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> MACUtils.</span><span style=\\"color:#6F42C1\\">getMac</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String str </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> Build.MODEL;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> MD5Util.</span><span style=\\"color:#6F42C1\\">getStringMD5_32</span><span style=\\"color:#24292E\\">(substring </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> \\"k3k7a3mM\\"</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> str).</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">8</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">24</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getEncryptionParams</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str2</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String encrypKey </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> getEncrypKey</span><span style=\\"color:#24292E\\">(str2);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> String</span><span style=\\"color:#24292E\\">(Base64.</span><span style=\\"color:#6F42C1\\">encodeBase64</span><span style=\\"color:#24292E\\">(AES.</span><span style=\\"color:#6F42C1\\">encrypt</span><span style=\\"color:#24292E\\">(str.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), encrypKey.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), encrypKey.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">())));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getSoEncryptionParams</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str2</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str3</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> android.util.Base64.</span><span style=\\"color:#6F42C1\\">encodeToString</span><span style=\\"color:#24292E\\">(MainActivity.</span><span style=\\"color:#6F42C1\\">getJniApi</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">encodeAES</span><span style=\\"color:#24292E\\">(str.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), str3.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), str2.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">()), </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getSoDecrypt</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str2</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        try</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> String</span><span style=\\"color:#24292E\\">(MainActivity.</span><span style=\\"color:#6F42C1\\">getJniApi</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">decodeAES</span><span style=\\"color:#24292E\\">(str.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), android.util.Base64.</span><span style=\\"color:#6F42C1\\">decode</span><span style=\\"color:#24292E\\">(str2.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">)));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        } </span><span style=\\"color:#D73A49\\">catch</span><span style=\\"color:#24292E\\"> (Exception </span><span style=\\"color:#E36209\\">e</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            e.</span><span style=\\"color:#6F42C1\\">printStackTrace</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#032F62\\"> \\"\\"</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getDecrypt</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> AES.</span><span style=\\"color:#6F42C1\\">decrypt</span><span style=\\"color:#24292E\\">(str, </span><span style=\\"color:#6F42C1\\">getDecrypKey</span><span style=\\"color:#24292E\\">(), </span><span style=\\"color:#6F42C1\\">getDecrypKey</span><span style=\\"color:#24292E\\">(), </span><span style=\\"color:#032F62\\">\\"utf8\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br></div></div><p>通过上面这段 JAVA 代码，我们知道加密的 key 是基于 MAC 地址信息进行生成的，传入的 str 参数其实是 <code>utctime</code> 。而解密 key 是基于 MAC 地址和 MODEL 信息，返回值的解密并没有用到 <code>utctime</code> 。返回信息的时候考虑到网络延迟 <code>utctime</code> 不是一个靠谱的参数。这里的 JAVA 逻辑是非核心请求的算法，我们想知道核心的播放列表信息的时候，发现它使用的是 <code>getSoEncryptionParams</code> 这个方法调用，而这个方法经过分析是调用 C++ 生成的 so 文件。逆向难度又上了一个台阶。顺便说下，经过 JAVA 代码分析 key 和 iv 其实是相同的参数。</p>\\n<h3 id=\\"so-文件分析\\" tabindex=\\"-1\\">so 文件分析 <a class=\\"header-anchor\\" href=\\"#so-文件分析\\" aria-label=\\"Permalink to &quot;so 文件分析&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>C++ 编译成 so 文件本质就是一个二进制文件。要想分析这个二进制文件需要很高的汇编功底和 C 语言知识，因为有些工具可以把二进制反编译成可读的 C 语言。经过同学点拨，使用了 <code>IDA Pro</code> 和 <code>Ghidra</code> 两个工具来对 so 文件进行逆向。so 文件的分析非常复杂，这里就只说结论了，so 里面分析出来的加解密算法和 JAVA 是一样的，但是中间拼接的字符串是不一样的。只要找到了核心的字符串就能完成请求的加解密。关于请求的解密，针对非英文字符，请使用 UTF-8 编码方式，由于我使用的工具默认采用 ASCII 编码，导致中文乱码，花了一段时间才找到原因。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>出于满足自己的好奇心，在各路同学的指点下，进行了安卓程序的逆向分析。非常有趣并且学到了很多知识，最后拿到了播放列表，但发现是基于一个私有的 <code>tvbus</code> 协议，没法移植到别的 APP 上使用，只能到此作罢。但是这次逆向分析的收获还是不少，在此记录一下。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/CodingGay/BlackDex\\" target=\\"_blank\\" rel=\\"noreferrer\\">BlackDex</a></p>\\n<p><a href=\\"https://github.com/skylot/\\" target=\\"_blank\\" rel=\\"noreferrer\\">jadx</a></p>\\n<p><a href=\\"https://www.charlesproxy.com/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Charles</a></p>\\n<p><a href=\\"https://gchq.github.io/CyberChef/\\" target=\\"_blank\\" rel=\\"noreferrer\\">CyberChef</a></p>\\n<p><a href=\\"https://github.com/NationalSecurityAgency/ghidra\\" target=\\"_blank\\" rel=\\"noreferrer\\">Ghidra</a></p>\\n<p><a href=\\"https://hex-rays.com/ida-pro/\\" target=\\"_blank\\" rel=\\"noreferrer\\">IDA Pro</a></p>\\n<p><a href=\\"https://gist.github.com/acgotaku/091a7a5d181b3211392b0fbdaf37d347\\" target=\\"_blank\\" rel=\\"noreferrer\\">EncryptRule</a></p>\\n"},{"title":"Archlinux下Galaxy Nexus刷机并root","url":"/posts/2013-07-20-archlinux-flash-android/","date":"2013-07-20 14:12","tags":["linux","android"],"html":"<p>安卓本来就是 Linux 衍生的,所以必然可以用 Linux 系统进行刷机,而且效果比 Win 还要好.不需要安装驱动,只需要安装 adb 和 fastboot 即可.</p>\\n<h2 id=\\"安装相关依赖\\" tabindex=\\"-1\\">安装相关依赖 <a class=\\"header-anchor\\" href=\\"#安装相关依赖\\" aria-label=\\"Permalink to &quot;安装相关依赖&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先通过 AUR 源安装[android-sdk](<a href=\\"https://aur.archlinux.org/packages/android-sdk/%E5%92%8C%5Bandroid-sdk-platform-tools%5D(https://aur.archlinux.org/packages/android-sdk-platform-tools/)%E7%9B%B8%E5%85%B3%E7%9A%84wiki%E5%9C%A8\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aur.archlinux.org/packages/android-sdk/和[android-sdk-platform-tools](https://aur.archlinux.org/packages/android-sdk-platform-tools/)相关的wiki在</a> <a href=\\"https://wiki.archlinux.org/index.php/Android\\" target=\\"_blank\\" rel=\\"noreferrer\\">这里</a></p>\\n<p>通过 <code>yaourt -Ql android-sdk-platform-tools</code> 可以发现 adb 和 fastboot 都安装在<code>/opt/android-sdk/platform-tools</code> 目录下,但是 PATH 环境变量没有这个值,所以无法在终端里直接调用必须先设置 PATH 变量 <code>export PATH=&quot;${PATH}:/opt/android-sdk/platform-tools&quot;</code>在 .xinitrc 里面添加这句就可以使 X 下的终端 PATH 环境变量被添加.也可以直接执行,当终端关闭时 PATH 变量的设置也失效.</p>\\n<h2 id=\\"配置-adb\\" tabindex=\\"-1\\">配置 ADB <a class=\\"header-anchor\\" href=\\"#配置-adb\\" aria-label=\\"Permalink to &quot;配置 ADB&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前面提供的 wiki 已经很详细的讲述如何进行<a href=\\"https://wiki.archlinux.org/index.php/Android#Connecting_to_a_real_device_-_Android_Debug_Bridge_.28ADB.29\\" target=\\"_blank\\" rel=\\"noreferrer\\">ADB 的配置了</a></p>\\n<h2 id=\\"测试-fastboot\\" tabindex=\\"-1\\">测试 FASTBOOT <a class=\\"header-anchor\\" href=\\"#测试-fastboot\\" aria-label=\\"Permalink to &quot;测试 FASTBOOT&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>fastboot 模式（上下音量键和开机键一起按）,可以看到一个大大的 Start 画面,这就是进入了 fastboot.或者使用命令<code>adb reboot bootloader</code>。此时把手机用 USB 连入电脑. 在终端里面输入 fastboot devices 如果提示 no permission 即是普通用户没有权限。这时候就需要切换到 root 用户进行执行.如果输入一串数字.则说明系统识别到了你的手机.</p>\\n<h2 id=\\"刷机开始\\" tabindex=\\"-1\\">刷机开始 <a class=\\"header-anchor\\" href=\\"#刷机开始\\" aria-label=\\"Permalink to &quot;刷机开始&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先要下载<a href=\\"https://developers.google.com/android/nexus/images\\" target=\\"_blank\\" rel=\\"noreferrer\\">固件</a>下载下来的 tgz 文件解压即可看到有个 flash-all.sh 的脚本。首先 <code>chmod +x flash-all.sh</code> 赋予脚本执行权限，然后执行这个脚本即可,如果有大量输出则说明刷机正常进行中.</p>\\n<h2 id=\\"后续-root\\" tabindex=\\"-1\\">后续 ROOT <a class=\\"header-anchor\\" href=\\"#后续-root\\" aria-label=\\"Permalink to &quot;后续 ROOT&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>ROOT 的话首先需要刷 recovery,我们先下载<a href=\\"http://www.clockworkmod.com/rommanager\\" target=\\"_blank\\" rel=\\"noreferrer\\">recovery</a>找到自己型号的 recovery 进行下载,我的是 recovery-clockwork-touch-6.0.3.3-maguro.img，touch 代表的是是否支持触摸.否则只能用音量键和开机键进行选择和确定.然后下载 superSU 的 ZIP 压缩包,目前版本是<a href=\\"http://download.chainfire.eu/339/SuperSU/UPDATE-SuperSU-v1.41.zip?retrieve_file=1\\" target=\\"_blank\\" rel=\\"noreferrer\\">1.41</a> ,ZIP 格式不要解压.放入 SD 卡中.<code>adb push UPDATE-SuperSU-v1.41.zip /sdcard/</code>将手机关机进入 fastboot 模式,应该先解锁, <code>fastboot oem unlock</code>然后刷入 recovery <code>fastboot flash recovery recovery-clockwork-touch-6.0.3.3-maguro.img</code>按下音量键调至 recovery，按开机键进入，手机会自动重启进入 recovery。choose zip from SDcard，然后依次进入，最终选择 UPDATE-SuperSU-v1.41.zip，确认安装.</p>\\n<p>注：如果提示是否清除 recovery flash，请选 No，否则下次推送时无法进行 OTA 更新.安装完成后依次返回.这个步骤不会影响 OTA 更新,并且 OTA 更新之后会自动解决 ROOT 的问题,无需再次 ROOT.</p>\\n<h2 id=\\"adb-小技巧\\" tabindex=\\"-1\\">ADB 小技巧 <a class=\\"header-anchor\\" href=\\"#adb-小技巧\\" aria-label=\\"Permalink to &quot;ADB 小技巧&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>刷机之后需要一大堆 APK 软件安装怎么办 adb 本身只有单个 APK 安装的功能，通过 <code>ls -1 *.apk | xargs -l adb install</code> 这个命令可以批量的把一个文件夹下的所以 APK 安装上去,而且还是静默安装. 不过首先要打开 ADB 调试才行.</p>\\n<h2 id=\\"手机-mtp-连接-linux-电脑\\" tabindex=\\"-1\\">手机 MTP 连接 Linux 电脑 <a class=\\"header-anchor\\" href=\\"#手机-mtp-连接-linux-电脑\\" aria-label=\\"Permalink to &quot;手机 MTP 连接 Linux 电脑&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MTP 是微软发明的东西....当然不好用\\n目前有两种解决方案一种是 GMTP,速度较慢,因为第一次和之后所有操作之后都会全部索引一遍文件列表.第二种是 gvfs-mtp 结合 thunar 使用,可以自动挂载,如果无法挂载可以使用 <code>lsusb</code> 命令.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Bus 001 Device 117: ID 04e8:6860 Samsung Electronics Co., Ltd GT-I9100 Phone [Galaxy S II], GT-I9300 Phone [Galaxy S III], GT-P7500 [Galaxy Tab 10.1]</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>可以看到我的设备号,然后在地址栏里面输入 <code>mtp://[usb:001,117]/</code>。第一个数字是 Bus 号,第二个数字是设备号.</p>\\n"}]},"relativePath":"tags/android/index.md","filePath":"tags/[slug].md"}'),e={name:"tags/android/index.md"};function l(o,p,r,t,c,i){return a(),n("div")}const b=s(e,[["render",l]]);export{y as __pageData,b as default};
